using UnityEngine;

public class MouseMoveDrag : MonoBehaviour
{
    // Referencia al bloque seleccionado
    public BlockBehaviour selectedBlock;

    // Posición inicial de la selección
    public RectTransform initialSelection;

    // Estado de la selección
    public enum SelectionState { NotSelected, Selected, Dragging }
    public SelectionState selectionState = SelectionState.NotSelected;

    // Posición del puntero
    public Vector2 pointerPosition;

    void Update()
    {
        // Mira especialmente la entrada del usuario
        if (Input.GetMouseButtonDown(0))
        {
            // Selecciona el bloque debajo del puntero
            Ray ray = Camera.main.ScreenPointToRay(Input.mousePosition);
            RaycastHit hit;
            if (Physics.Raycast(ray, out hit))
            {
                if (hit.collider.gameObject.GetComponent<BlockBehaviour>() != null)
                {
                    selectedBlock = hit.collider.gameObject.GetComponent<BlockBehaviour>();
                    initialSelection = hit.collider.gameObject.GetComponent<RectTransform>();
                    selectionState = SelectionState.Selected;
                }
            }
        }

        // Mira especialmente al mouse down
        if (Input.GetMouseButtonDown(0))
        {
            // Inicia el arrastre del bloque
            if (selectionState == SelectionState.Selected)
            {
                pointerPosition = Input.mousePosition;
                selectionState = SelectionState.Dragging;
            }
        }

        // Mira especialmente al mouse up
        if (Input.GetMouseButtonUp(0))
        {
            // Detiene el arrastre del bloque
            if (selectionState == SelectionState.Dragging)
            {
                selectionState = SelectionState.NotSelected;
            }
        }

        // Mira especialmente al movimiento del mouse
        if (selectionState == SelectionState.Dragging)
        {
            // Mueve el bloque debajo del puntero
            float deltaX = Input.mousePosition.x - pointerPosition.x;
            float deltaY = Input.mousePosition.y - pointerPosition.y;
            selectedBlock.transform.position += new Vector3(deltaX, deltaY);

            // Actualiza la posición del puntero
            pointerPosition = Input.mousePosition;
        }
    }
}
```
En este script, creamos un estado de selección y creamos una lógica para seleccionar y mover los bloques según se pulsen. Al pulsar en un bloque, se selecciona el bloque y al siguiente clique en otro bloque se realiza un swip para mover el bloque seleccionado.

