#include <random>

#define N 1000000
#define METHOD_COUNT 3

const char* methods[] = {"Прямоугольников", "Трапеций", "Парабол (метод Симпсона)"};

void calculateIntegral(int method, int numThreads) {
    HANDLE hMutex = CreateMutex(NULL, FALSE, NULL);
    HANDLE hSemaphore = CreateSemaphore(NULL, 1, numThreads, NULL);

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<double> dis(0.0, 1.0);

    double integral = 0.0;
    int numPoints = N / numThreads;

    for (int i = 0; i < numPoints; i++) {
        double x = dis(gen);
        double y = std::sin(x);

        switch (method) {
        case 0: // Прямоугольники
            integral += y * (x + 1.0 / numPoints);
            break;
        case 1: // Трапеций
            integral += (y * (x + 1.0 / numPoints) + y * (x + 1.0 / numPoints)) * 1.0 / numPoints;
            break;
        case 2: // Парабол (метод Симпсона)
            integral += (y * (x + 1.0 / numPoints) + 4.0 * y * (x + 1.0 / (2.0 * numPoints)) + y * (x + 1.0 / numPoints)) * 1.0 / (3.0 * numPoints);
            break;
        }

        ReleaseSemaphore(hSemaphore, 1, NULL);
