import heapq

class FibonacciHeap:
    def __init__(self):
        self.heap = []
        self.degree = 0

    def insert(self, node, distance):
        self.heap.append((distance, node))
        self.degree += 1

    def get_min(self):
        return min(self.heap)

    def extract_min(self):
        min_distance, min_node = self.get_min()
        self.heap.remove((min_distance, min_node))
        self.degree -= 1
        return min_node, min_distance

    def decrease_key(self, node, new_distance):
        for i, (distance, n) in enumerate(self.heap):
            if n == node:
                self.heap[i] = (new_distance, node)
                self.heap = sorted(self.heap)
                break

def dijkstra(line_length, start, destination):
    unknown_points = FibonacciHeap()
    known_points = set()
    distance = {start: 0}

    node, distance_to_node = unknown_points.insert(start, 0)
    unknown_points.decrease_key(node, distance_to_node)

    while node != destination:
        node, distance_to_node = unknown_points.extract_min()
        known_points.add(node)

        for adjacent_node in [n for n, d in line_length.items() if n == node]:
            if adjacent_node not in known_points:
                new_distance = distance_to_node + d
                if adjacent_node not in distance or new_distance < distance[adjacent_node]:
                    distance[adjacent_node] = new_distance
                    unknown_points.decrease_key(adjacent_node, new_distance)

    return distance[destination]

