```jsx
import React, { Component } from 'react';
import { GoogleLogin } from 'react-google-login';
import { Redirect } from 'react-router-dom';
import { MuiThemeProvider, createMuiTheme } from '@material-ui/core/styles';
import Conexion from './Conexion';

const theme = createMuiTheme({
  palette: {
    primary: {
      main: '#3498db',
    },
    secondary: {
      main: '#e74c3c',
    },
  },
});

class Auth extends Component {
  constructor(props) {
    super(props);
    this.state = {
      token: null,
      isAuthenticated: false,
    };
  }

  successResponse = (response) => {
    const { accessToken } = response.tokenId;
    this.setState({ token: accessToken, isAuthenticated: true });
  };

  failureResponse = (response) => {
    console.error('OAuth authentication failed:', response);
  };

  login() {
    const { clientId, clientSecret } = this.props;
    const redirect_uri = 'http://localhost:3000'; // replace with your redirect URI
    const scope = 'email profile'; // replace with the scopes you need
    const googleAuth = new GoogleAuth({
      clientId,
      clientSecret,
      redirect_uri,
      scope,
    });
    googleAuth.signIn().then(this.successResponse.bind(this), this.failureResponse.bind(this));
  }

  render() {
    if (this.state.isAuthenticated) {
      return <Redirect to="/protected" />;
    }
    return (
      <MuiThemeProvider theme={theme}>
        <GoogleLogin
          clientId={this.props.clientId}
          onSuccess={this.successResponse.bind(this)}
          onFailure={this.failureResponse.bind(this)}
          render={renderProps => (
            <button onClick={renderProps.onClick} disabled={renderProps.disabled}>
              Sign in with Google
            </button>
          )}
        />
      </MuiThemeProvider>
    );
  }
}

export default Auth;
```
